#include <bits/stdc++.h>
#define second second
#define first first
#define fast_io ios::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr)
#define output(n) return cout << n, 0
#define set_prec(n) cout << fixed << setprecision(n)
#define push_back emplace_back
#define int long long
#define long_double long double
#pragma GCC optimize("Ofast,no-stack-protector,unroll-loops")
using namespace std;

const int MAX_LIMIT = 1e6 + 100, INF_LIMIT = 1e9 + 7, MOD_LIMIT = 1e9 + 7, P_CONST = 6151, T_CONST = 2000, SQ_CONST = 280, LOG_SZ = 64, LOG2_SZ = 34;
typedef pair<int, int> pair_int;

int total_numbers, base_d;
vector<int> digits;

struct node {
    int matrix[LOG2_SZ][LOG2_SZ], temp[LOG2_SZ][LOG2_SZ];
    bool visited[LOG2_SZ], toggled[LOG2_SZ];

    void merge(node &other) {
        for (int i = 0; i <= base_d; i++) {
            for (int j = 0; j <= base_d; j++) {
                matrix[i][j] = 0;
                for (int k = 0; k <= base_d; k++)
                    matrix[i][j] = (matrix[i][j] + matrix[k][j] * other.matrix[i][k]) % MOD_LIMIT;
            }
        }
        for (int i = 0; i < base_d; i++) {
            if (visited[i] && !other.visited[i]) {
                for (int j = 0; j <= base_d; j++)
                    matrix[i][j] = matrix[i][j];
            }
            if (!visited[i] && other.visited[i]) {
                for (int j = 0; j <= base_d; j++)
                    matrix[j][i] = other.matrix[j][i];
            }
            visited[i] |= other.visited[i];
        }
        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                matrix[i][j] = matrix[i][j];
    }

    void reset() {
        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                matrix[i][j] = temp[i][j] = 0;
    }

    void shift(int shift_value) {
        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                temp[i][j] = 0;
        for (int i = 0; i < base_d; i++) {
            for (int j = 0; j < base_d; j++)
                temp[(i + shift_value) % base_d][(j + shift_value) % base_d] = matrix[i][j];
            temp[(i + shift_value) % base_d][base_d] = matrix[i][base_d];
        }
        for (int i = 0; i < base_d; i++)
            temp[base_d][(i + shift_value) % base_d] = matrix[base_d][i];
        temp[base_d][base_d] = matrix[base_d][base_d];

        for (int i = 0; i <= base_d; i++)
            for (int j = 0; j <= base_d; j++)
                matrix[i][j] = temp[i][j];

        for (int i = 0; i < base_d; i++)
            toggled[i] = visited[(i + shift_value) % base_d];
        for (int i = 0; i < base_d; i++)
            visited[i] = toggled[i];
    }
} node_struct[LOG_SIZE], helper_struct[LOG_SIZE], temp_node_struct;

node fetch_node(int x) {
    int h = x, pw = 1, t_idx = -1;
    while (h >= base_d) {
        h /= base_d;
        pw *= base_d;
        t_idx++;
    }
    x %= pw;
    if (t_idx == -1)
        return helper_struct[h];
    node res_node = node_struct[t_idx];
    temp_node_struct = node_struct[t_idx];
    for (int i = 1; i < h; i++) {
        temp_node_struct.shift(1);
        res_node.merge(temp_node_struct);
    }
    temp_node_struct = node_struct[t_idx];
    temp_node_struct = fetch_node(x);
    temp_node_struct.shift(h);
    res_node.merge(temp_node_struct);
    return res_node;
}

int main() {
    fast_io;
    cin >> total_numbers >> base_d;
    total_numbers--;
    int temp_total = total_numbers;
    while (total_numbers) {
        digits.push_back(total_numbers % base_d);
        total_numbers /= base_d;
    }
    node_struct[0].matrix[base_d][base_d] = 2;
    node_struct[0].matrix[base_d][0] = -1;
    node_struct[0].matrix[0][base_d] = 1;
    node_struct[0].visited[0] = true;
    for (int i = 1; i < base_d; i++) {
        node_struct[i].matrix[base_d][base_d] = 2;
        node_struct[i].matrix[base_d][i] = -1;
        node_struct[i].matrix[i][base_d] = 1;
        node_struct[i].visited[i] = true;
        helper_struct[0].merge(node_struct[i]);
        node_struct[i] = helper_struct[0];
    }
    for (int i = 1; i <= (int)digits.size(); i++) {
        node_struct[i] = node_struct[i - 1];
        temp_node_struct = node_struct[i - 1];
        for (int j = 1; j < base_d; j++) {
            temp_node_struct.shift(1);
            helper_struct[i].merge(temp_node_struct);
        }
    }
    node final_res = fetch_node(temp_total);
    cout << final_res.matrix[base_d][base_d] << "\n";
    return 0;
}
